namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly string[] _templates =
    [
        "Your build completed successfully.",
        "New comment on your pull request.",
        "Deployment to production finished.",
        "Security scan found no issues.",
        "Team member requested a review.",
        "Scheduled backup completed.",
        "New user signed up.",
        "Server CPU usage exceeded 90%.",
        "Certificate renewal reminder.",
        "Weekly report is ready."
    ];

    /// <summary>Returns a seeded initial batch of notifications.</summary>
    public List<NotificationItem> GetInitialNotifications()
    {
        var now = DateTime.UtcNow;
        return
        [
            new() { Id = _nextId++, Message = "Welcome! You have new updates.",        Timestamp = now.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile was viewed 5 times today.", Timestamp = now.AddMinutes(-7) },
            new() { Id = _nextId++, Message = "System maintenance scheduled tonight.",  Timestamp = now.AddMinutes(-3) },
        ];
    }

    /// <summary>Simulates checking for new notifications (0-1 per call).</summary>
    public List<NotificationItem> CheckForNewNotifications()
    {
        // ~40 % chance of a new notification each poll
        if (Random.Shared.Next(0, 5) < 2)
        {
            var msg = _templates[Random.Shared.Next(_templates.Length)];
            return [new() { Id = _nextId++, Message = msg, Timestamp = DateTime.UtcNow }];
        }

        return [];
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@inject PersistentComponentState ApplicationState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>#@n.Id</strong> &mdash; @n.Message
                </div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@if (isPolling)
{
    <p class="mt-3 text-success">&#x1f7e2; Live &mdash; polling every 5 s</p>
}

@code {
    private List<NotificationItem> notifications = new();
    private CancellationTokenSource? cts;
    private PersistingComponentStateSubscription persistSub;
    private bool isPolling;

    protected override void OnInitialized()
    {
        // Re-hydrate from persisted state if available (interactive render),
        // otherwise fetch from the service (SSR / prerender).
        persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (ApplicationState.TryTakeFromJson<List<NotificationItem>>(
                "notifications", out var restored))
        {
            notifications = restored!;
        }
        else
        {
            notifications = Svc.GetInitialNotifications();
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", notifications);
        return Task.CompletedTask;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires in interactive mode — safe to start polling.
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
            isPolling = true;
            StateHasChanged();
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), token);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newer = Svc.CheckForNewNotifications();
            if (newer.Count > 0)
            {
                notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        persistSub.Dispose();

        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

