+@page "/notifications"
+@rendermode InteractiveServer
+@using NotificationsApp.Services
+@inject NotificationService Svc
+@inject PersistentComponentState ApplicationState
+@implements IAsyncDisposable
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>
+    Notifications
+    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
+</h1>
+
+@if (notifications.Count == 0)
+{
+    <p><em>No notifications.</em></p>
+}
+else
+{
+    <ul class="list-group mt-3">
+        @foreach (var n in notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <div>
+                    <strong>#@n.Id</strong> &mdash; @n.Message
+                </div>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@if (isPolling)
+{
+    <p class="mt-3 text-success">&#x1f7e2; Live &mdash; polling every 5 s</p>
+}
+
+@code {
+    private List<NotificationItem> notifications = new();
+    private CancellationTokenSource? cts;
+    private PersistingComponentStateSubscription persistSub;
+    private bool isPolling;
+
+    protected override void OnInitialized()
+    {
+        // Re-hydrate from persisted state if available (interactive render),
+        // otherwise fetch from the service (SSR / prerender).
+        persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);
+
+        if (ApplicationState.TryTakeFromJson<List<NotificationItem>>(
+                "notifications", out var restored))
+        {
+            notifications = restored!;
+        }
+        else
+        {
+            notifications = Svc.GetInitialNotifications();
+        }
+    }
+
+    private Task PersistNotifications()
+    {
+        ApplicationState.PersistAsJson("notifications", notifications);
+        return Task.CompletedTask;
+    }
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // OnAfterRender only fires in interactive mode — safe to start polling.
+            cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(cts.Token);
+            isPolling = true;
+            StateHasChanged();
+        }
+
+        await Task.CompletedTask;
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken token)
+    {
+        while (!token.IsCancellationRequested)
+        {
+            try
+            {
+                await Task.Delay(TimeSpan.FromSeconds(5), token);
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+
+            var newer = Svc.CheckForNewNotifications();
+            if (newer.Count > 0)
+            {
+                notifications.InsertRange(0, newer);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        persistSub.Dispose();
+
+        if (cts is not null)
+        {
+            await cts.CancelAsync();
+            cts.Dispose();
+        }
+    }
