namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly string[] _templates =
    [
        "Your build completed successfully.",
        "New comment on your pull request.",
        "Deployment to production finished.",
        "Security scan found no issues.",
        "Team member requested a review.",
        "Scheduled backup completed.",
        "New user signed up.",
        "Server CPU usage exceeded 90%.",
        "Certificate renewal reminder.",
        "Weekly report is ready."
    ];

    /// <summary>Returns a seeded initial batch of notifications.</summary>
    public List<NotificationItem> GetInitialNotifications()
    {
        var now = DateTime.UtcNow;
        return
        [
            new() { Id = _nextId++, Message = "Welcome! You have new updates.",        Timestamp = now.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile was viewed 5 times today.", Timestamp = now.AddMinutes(-7) },
            new() { Id = _nextId++, Message = "System maintenance scheduled tonight.",  Timestamp = now.AddMinutes(-3) },
        ];
    }

    /// <summary>Simulates checking for new notifications (0-1 per call).</summary>
    public List<NotificationItem> CheckForNewNotifications()
    {
        // ~40 % chance of a new notification each poll
        if (Random.Shared.Next(0, 5) < 2)
        {
            var msg = _templates[Random.Shared.Next(_templates.Length)];
            return [new() { Id = _nextId++, Message = msg, Timestamp = DateTime.UtcNow }];
        }

        return [];
    }
}

